#!/bin/bash
set -e
echo "================================"
echo "   NEXUS DNS 一键部署 (自包含)"
echo "================================"
[ "$(id -u)" = "0" ] || { echo "请用 root 运行"; exit 1; }

echo "[1/7] 安装 Docker..."
if ! command -v docker >/dev/null 2>&1; then
  curl -fsSL https://get.docker.com | sh -s docker --mirror Aliyun
fi
systemctl enable --now docker 2>/dev/null || true
(command -v apt-get >/dev/null && apt-get install -y unzip openssl >/dev/null 2>&1) || true

echo "[2/7] 配置 Docker 国内镜像加速..."
mkdir -p /etc/docker
cat > /etc/docker/daemon.json <<'EOF'
{"registry-mirrors":["https://docker.1ms.run","https://docker.m.daocloud.io","https://docker.xuanyuan.me","https://hub.rat.dev"]}
EOF
systemctl restart docker 2>/dev/null || true

echo "[3/7] 释放 53 端口..."
if systemctl is-active systemd-resolved >/dev/null 2>&1; then
  systemctl stop systemd-resolved; systemctl disable systemd-resolved
fi

echo "[4/7] 解包（内嵌，无需外网下载）..."
mkdir -p /opt/nexus-dns && cd /opt/nexus-dns
cat > dns-panel.zip.b64 <<'B64EOF'

B64EOF
base64 -d dns-panel.zip.b64 > dns-panel.zip
unzip -oq dns-panel.zip
cd dns-panel
cp -f .env.example .env
TOKEN=$(openssl rand -hex 16 2>/dev/null || echo nexus$RANDOM)
sed -i "s/change-me-to-a-random-string/$TOKEN/" .env

echo "[5/7] 拉取镜像并启动（首次拉50万规则约3-5分钟）..."
docker compose up -d --build

echo "[6/7] 放行本机防火墙..."
(command -v ufw >/dev/null && ufw allow 53/tcp && ufw allow 53/udp && ufw allow 3000/tcp) >/dev/null 2>&1 || true

echo "[7/7] 等待服务就绪..."
sleep 8
IP=$(curl -s --max-time 5 ifconfig.me 2>/dev/null || echo "你的公网IP")
echo ""
echo "================================"
echo " 部署完成！"
echo " 面板: http://$IP:3000"
echo " 账号: admin / Admin123456"
echo " DNS : $IP:53"
echo ""
echo " [重要] 去阿里云控制台放行安全组端口:"
echo "    TCP 3000  /  TCP 53  /  UDP 53"
echo " 首次加载规则需3-5分钟，稍后访问面板。"
echo "================================"
